#!/usr/bin/env bash
# Generated by scripts/ci/vm-lab.py from the lab files. Do not edit; change
# the lab files and run: python3 scripts/ci/vm-lab.py <lab directory>
# astrona pipes this file alone into the lab VM, where it runs as the VM
# administrator user. It builds the one-node kubeadm cluster, writes the lab
# files to /opt/astrona-lab and runs bootstrap/setup.sh from there.
set -euo pipefail
cluster="astro-ats-032-lab-040-03-02"
# The learner logs in as student, so student gets the admin kubeconfig too.
kube_users=(--user "$(id -un)")
getent passwd student >/dev/null && kube_users+=(--user student)
sudo /usr/local/sbin/astrona-kubeadm-init --node-name controlplane --cluster-name "$cluster" "${kube_users[@]}"
lab="/opt/astrona-lab"
sudo rm -rf "$lab"
write_file() {
  sudo mkdir -p "$(dirname "$lab/$2")"
  sudo tee "$lab/$2" >/dev/null
  sudo chmod "$1" "$lab/$2"
}
write_file 0644 bootstrap/helpers.sh <<'ASTRONA_LAB_FILE'
# Helper functions for the setup and solution scripts of a qemu lab.
# The scripts run inside the lab VM, which is the only node of the cluster:
# node_name and worker_name both name it, and node commands run with sudo.
# The calling script sets node_name, worker_name and namespace after its
# context guard.

run_on_node() {
  sudo "$@"
}

run_on_worker() {
  sudo "$@"
}

# Print the command line of the newest process with this program name,
# one argument on each line. Prints nothing when the process is not running.
process_arguments() {
  local program="$2" pid
  pid="$(sudo pgrep -n -f "^(/[^ ]*/)?$program( |\$)" || true)"
  if [[ -n "$pid" ]]; then
    sudo cat "/proc/$pid/cmdline" 2>/dev/null | tr '\0' '\n' || true
  fi
}

# Wait until the running process has (present) or no longer has (absent)
# one exact argument, for example --profiling=false.
wait_for_argument() {
  local container="$1" program="$2" argument="$3" state="$4" arguments attempt
  for attempt in $(seq 1 80); do
    arguments="$(process_arguments "$container" "$program")"
    if [[ -n "$arguments" ]]; then
      if [[ "$state" == present ]] && grep -qxF -- "$argument" <<<"$arguments"; then
        return 0
      fi
      if [[ "$state" == absent ]] && ! grep -qxF -- "$argument" <<<"$arguments"; then
        return 0
      fi
    fi
    sleep 3
  done
  printf 'Timed out: %s argument %s is not %s\n' "$program" "$argument" "$state" >&2
  return 1
}

# Wait until the API server answers /readyz with ok.
wait_for_api() {
  local attempt
  for attempt in $(seq 1 100); do
    if [[ "$(kubectl --request-timeout=3s get --raw=/readyz 2>/dev/null)" == ok ]]; then
      return 0
    fi
    sleep 3
  done
  printf 'Timed out waiting for the API server\n' >&2
  return 1
}

# Wait until the Ready condition of a kube-system pod has one value (True or
# False). The mirror pod of a static pod can be replaced while the kubelet
# restarts it, so a missing pod counts as "not yet".
wait_for_pod_ready() {
  local pod="$1" expected="$2" attempt
  for attempt in $(seq 1 60); do
    if [[ "$(kubectl -n kube-system get pod "$pod" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null)" == "$expected" ]]; then
      return 0
    fi
    sleep 3
  done
  printf 'Timed out waiting for pod %s Ready=%s\n' "$pod" "$expected" >&2
  return 1
}

# Edit a static pod manifest the safe way: copy it to a work directory
# outside /etc/kubernetes/manifests, run sed on the copy, move it back.
edit_manifest() {
  local component="$1" expression="$2"
  local manifest="/etc/kubernetes/manifests/$component.yaml" copy="/etc/kubernetes/edit/$component.yaml"
  run_on_node mkdir -p /etc/kubernetes/edit
  run_on_node cp -p "$manifest" "$copy"
  run_on_node sed -i "$expression" "$copy"
  run_on_node mv "$copy" "$manifest"
}

# Replace or add one top-level field in the kubelet configuration file.
set_kubelet_field() {
  run_on_worker sed -i "/^$1:/d" /var/lib/kubelet/config.yaml
  run_on_worker sh -c "printf '\n%s: %s\n' '$1' '$2' >> /var/lib/kubelet/config.yaml"
}

# Wait until the effective kubelet configuration (configz) holds a text
# (present, the default) or no longer holds it (absent).
wait_for_configz() {
  local expected="$1" state="${2:-present}" attempt current
  for attempt in $(seq 1 60); do
    if current="$(kubectl --request-timeout=3s get --raw "/api/v1/nodes/$worker_name/proxy/configz" 2>/dev/null)"; then
      if [[ "$state" == present ]] && grep -qF -- "$expected" <<<"$current"; then
        return 0
      fi
      if [[ "$state" == absent ]] && ! grep -qF -- "$expected" <<<"$current"; then
        return 0
      fi
    fi
    sleep 3
  done
  printf 'Timed out waiting for kubelet configuration %s %s\n' "$expected" "$state" >&2
  return 1
}

# Wait until the worker node reports Ready.
wait_for_worker() {
  kubectl wait --for=condition=Ready "node/$worker_name" --timeout=180s
}

# Run a short pod with the kube-bench image in the lab namespace, wait until
# it has finished and print its log. The pod reads only its own image.
kube_bench_image_output() {
  local name="$1" script="$2"
  kubectl -n "$namespace" delete pod "$name" --ignore-not-found --wait=true >/dev/null
  kubectl -n "$namespace" run "$name" --restart=Never --image-pull-policy=IfNotPresent \
    --image=docker.io/aquasec/kube-bench:v0.10.6 --command -- sh -c "$script" >/dev/null
  kubectl -n "$namespace" wait --for=jsonpath='{.status.phase}'=Succeeded "pod/$name" --timeout=120s >/dev/null
  kubectl -n "$namespace" logs "pod/$name"
  kubectl -n "$namespace" delete pod "$name" --wait=false >/dev/null
}
ASTRONA_LAB_FILE
write_file 0755 bootstrap/setup.sh <<'ASTRONA_LAB_FILE'
#!/usr/bin/env bash
# Bootstrap for lab ats-032-lab-040-03-02. vm/install.sh builds the one-node
# cluster (node controlplane) and runs this script inside the lab VM from
# /opt/astrona-lab as the VM administrator user (passwordless sudo).
#
# Start state: the single node controlplane runs the two probe Pods and is
# cordoned for the maintenance window, but not drained. The ConfigMap
# maintenance-baseline records the containerd invocation ID and the probe Pod
# UIDs, so the graders can tell what changed. Nothing is pulled.

LAB_NAME=ats-032-lab-040-03-02
NODE=controlplane
NAMESPACE=starfleet-032-040-03-02

kube() {
  sudo -n kubectl --kubeconfig /etc/kubernetes/admin.conf "$@"
}

main() {
  set -euo pipefail

  # Context guard: run only against this VM's own cluster.
  local context="${ASTRONA_KUBE_CONTEXT:-kubernetes-admin@astro-$LAB_NAME}"
  if [ "$(kubectl config current-context)" != "$context" ]; then
    echo "Refusing to operate on another Kubernetes context" >&2
    exit 1
  fi

  kube apply -f - <<EOF
apiVersion: v1
kind: Namespace
metadata:
  name: $NAMESPACE
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: probe
  namespace: $NAMESPACE
spec:
  replicas: 2
  selector:
    matchLabels:
      app: probe
  template:
    metadata:
      labels:
        app: probe
    spec:
      containers:
      - name: probe
        image: docker.io/library/busybox:1.37.0
        imagePullPolicy: IfNotPresent
        command:
        - sh
        - -c
        - sleep 86400
        resources:
          requests:
            cpu: 10m
            memory: 16Mi
          limits:
            memory: 32Mi
EOF
  kube -n "$NAMESPACE" rollout status deployment/probe --timeout=180s </dev/null

  local invocation probe_uids
  invocation=$(systemctl show containerd --property=InvocationID --value)
  probe_uids=$(kube -n "$NAMESPACE" get pods -l app=probe -o jsonpath='{.items[*].metadata.uid}' </dev/null)
  kube -n "$NAMESPACE" create configmap maintenance-baseline \
    --from-literal=containerd-invocation="$invocation" \
    --from-literal=probe-uids="$probe_uids" </dev/null

  # The maintenance window has opened: the node is cordoned, but nothing has
  # been evicted yet.
  kube cordon "$NODE" </dev/null

  # Leave the student a shell that knows the cluster.
  if id student >/dev/null 2>&1; then
    echo 'source <(kubectl completion bash)' | sudo -n tee /etc/profile.d/kubectl-completion.sh >/dev/null
  fi

  kube get nodes -o wide </dev/null
}

main "$@"
ASTRONA_LAB_FILE
write_file 0755 solution/apply.sh <<'ASTRONA_LAB_FILE'
#!/usr/bin/env bash
# Reference solution for lab ats-032-lab-040-03-02, run by `astrona test`.
# vm/apply-solution.sh runs it inside the lab VM as the VM administrator user.
# It follows solution.md: drain the node, restart containerd, wait for Ready,
# uncordon. Every step is safe to run again.

LAB_NAME=ats-032-lab-040-03-02
NODE=controlplane
NAMESPACE=starfleet-032-040-03-02

kube() {
  sudo -n kubectl --kubeconfig /etc/kubernetes/admin.conf "$@" </dev/null
}

main() {
  set -euo pipefail

  # Context guard: run only against this VM's own cluster.
  local context="${ASTRONA_KUBE_CONTEXT:-kubernetes-admin@astro-$LAB_NAME}"
  if [ "$(kubectl config current-context)" != "$context" ]; then
    echo "Refusing to operate on another Kubernetes context" >&2
    exit 1
  fi

  kube drain "$NODE" --ignore-daemonsets --timeout=180s
  sudo -n systemctl restart containerd
  systemctl is-active containerd
  kube wait --for=condition=Ready "node/$NODE" --timeout=180s
  kube uncordon "$NODE"
  kube -n "$NAMESPACE" rollout status deployment/probe --timeout=180s
}

main "$@"
ASTRONA_LAB_FILE
write_file 0644 testing/check.py <<'ASTRONA_LAB_FILE'
#!/usr/bin/env python3
"""Grade a lab: resource contracts, bounded behavior checks and live.py.

Run with no argument to grade the whole lab, or with an outcome id to grade
one outcome. Each entry in requirements.json and each `if wants(...)` block
in live.py belongs to one outcome; an entry without an outcome is a guard
and runs for every outcome. config.yaml lists one validation script per
outcome (validation/validate-<id>.sh), each with its points. Like ATS020's
graders it prints one `PASS:` or `FAIL:` line.

Every run first checks that kubectl's current context is the lab's own:
ASTRONA_KUBE_CONTEXT when astrona sets it (an exam cluster sets its own),
otherwise the lab mode context in requirements.json. The node containers'
names and the container engine come from the environment astrona sets too,
so the same checks run on the lab's own cluster and on an exam cluster.

A qemu lab ("runtime": "qemu" in requirements.json) runs this file inside its
VM: the cluster is one kubeadm node named after the VM's host name (astrona
names the VM differently under `astrona test`), so NODE and WORKER are that
node and node_exec() runs the command on the VM with sudo.
"""
import json
import os
from pathlib import Path
import socket
import subprocess
import sys

DIRECTORY = Path(__file__).resolve().parent
REQUIREMENTS = json.loads((DIRECTORY / 'requirements.json').read_text())
CONTEXT = os.environ.get('ASTRONA_KUBE_CONTEXT') or REQUIREMENTS['context']
CLUSTER = os.environ.get('ASTRONA_KIND_CLUSTER') or REQUIREMENTS['cluster']
ENGINE = os.environ.get('ASTRONA_CONTAINER_ENGINE') or 'podman'
NAMESPACE = REQUIREMENTS['namespace']
QEMU = REQUIREMENTS.get('runtime') == 'qemu'
NODE = socket.gethostname() if QEMU else CLUSTER + '-control-plane'
WORKER = socket.gethostname() if QEMU else CLUSTER + '-worker'
SELECTED = sys.argv[1] if len(sys.argv) > 1 else None
MATCHED = set()


def wants(outcome):
    """True when this outcome is being graded (or the whole lab is)."""
    if SELECTED is None or SELECTED == outcome:
        MATCHED.add(outcome)
        return True
    return False


def selected(check):
    outcome = check.get('outcome')
    return outcome is None or wants(outcome)


def command(args, *, success=True):
    result = subprocess.run(args, capture_output=True, text=True, timeout=20)
    if success:
        assert result.returncode == 0, 'Required command failed: ' + args[0]
    return result


def kubectl(*args):
    return command(['kubectl', *args]).stdout.strip()


def node_exec(node, *args, success=True):
    """Run a command on a node (NODE or WORKER): in its container, or on the qemu VM."""
    prefix = ['sudo'] if QEMU else [ENGINE, 'exec', node]
    return command([*prefix, *args], success=success)


def get(kind, name, namespace=NAMESPACE):
    scope = ['-n', namespace] if namespace else []
    result = command(['kubectl', *scope, 'get', kind, name, '-o', 'json'], success=False)
    assert result.returncode == 0, f'Missing {kind} {name}' + (f' in namespace {namespace}' if namespace else '')
    return json.loads(result.stdout)


def contains(actual, expected):
    """Allow server-defaulted fields while preserving declared fields and lists."""
    if isinstance(expected, dict):
        return isinstance(actual, dict) and all(key in actual and contains(actual[key], value) for key, value in expected.items())
    if isinstance(expected, list):
        return isinstance(actual, list) and len(actual) == len(expected) and all(contains(left, right) for left, right in zip(actual, expected))
    return actual == expected


def resource_check(check):
    resource = get(check['kind'], check['name'], check.get('namespace', NAMESPACE))
    assert contains(resource, check['expected']), 'Required resource fields differ: ' + check['name']
    state = check.get('state')
    status = resource.get('status', {})
    if state == 'deployment':
        replicas = resource['spec'].get('replicas', 1)
        assert status.get('observedGeneration', 0) >= resource['metadata']['generation'], 'Current generation has not been observed'
        assert all(status.get(field, 0) == replicas for field in ('replicas', 'updatedReplicas', 'readyReplicas', 'availableReplicas')), 'Deployment rollout is incomplete'
    elif state == 'pod':
        assert status.get('phase') == 'Running' and any(condition['type'] == 'Ready' and condition['status'] == 'True' for condition in status.get('conditions', [])), 'Pod must be running and ready'
    elif state == 'job':
        assert status.get('succeeded', 0) == 1 and any(condition['type'] == 'Complete' and condition['status'] == 'True' for condition in status.get('conditions', [])), 'Job must complete successfully'
    elif state == 'pvc':
        assert status.get('phase') == 'Bound' and resource['spec'].get('volumeName'), 'Claim must bind to a volume'
    elif state == 'daemonset':
        desired = status.get('desiredNumberScheduled', 0)
        assert desired >= 2 and status.get('numberReady', 0) == desired and status.get('updatedNumberScheduled', 0) == desired, 'DaemonSet must cover both eligible nodes'
    return resource


def behavior_check(check):
    result = command(check['args'], success=not check.get('denied', False))
    if check.get('denied'):
        assert result.returncode == 1, 'Expected a bounded denied request, not a successful request or execution error'
        output = result.stdout + result.stderr
        assert any(marker in output.lower() for marker in check['failure_markers']), 'Request did not fail for the required reason'
    output = result.stdout.strip()
    if 'equals' in check:
        assert output == check['equals'], 'Command returned an unexpected value'
    for marker in check.get('contains', []):
        assert marker in output, 'Command did not return the expected application evidence'
    if 'json' in check:
        assert contains(json.loads(output), check['json']), 'Command returned an unexpected JSON contract'
    return result


def main():
    if kubectl('config', 'current-context') != CONTEXT:
        sys.exit('Refusing to operate on another Kubernetes context')
    for check in REQUIREMENTS.get('resources', []):
        if selected(check):
            resource_check(check)
    for check in REQUIREMENTS.get('behavior', []):
        if selected(check):
            behavior_check(check)
    extra = DIRECTORY / 'live.py'
    if extra.exists():
        exec(compile(extra.read_text(), str(extra), 'exec'), globals())
    assert SELECTED is None or SELECTED in MATCHED, 'Unknown outcome: ' + SELECTED
    print('PASS: ' + (SELECTED or 'every outcome'))


if __name__ == '__main__':
    try:
        main()
    except (AssertionError, KeyError, ValueError, subprocess.SubprocessError) as error:
        print('FAIL: ' + str(error))
        sys.exit(1)
ASTRONA_LAB_FILE
write_file 0644 testing/live.py <<'ASTRONA_LAB_FILE'
# Checks that read the containerd service on the lab VM and the probe Pods.
# check.py runs this file inside the lab VM with NODE, node_exec(), command(),
# kubectl(), get() and wants() already defined. The node is named
# controlplane, as on an exam cluster.
import json

NODE_NAME = 'controlplane'
NS = 'starfleet-032-040-03-02'


def baseline(key):
    """A value that the bootstrap recorded in the ConfigMap maintenance-baseline."""
    found = command(['kubectl', '-n', NS, 'get', 'configmap', 'maintenance-baseline', '-o', 'json'], success=False)
    if found.returncode != 0:
        return ''
    return (json.loads(found.stdout).get('data') or {}).get(key, '')


def systemd_property(name):
    return command(['systemctl', 'show', 'containerd', '--property=' + name, '--value'], success=False).stdout.strip()


if wants('runtime-restarted'):
    started = baseline('containerd-invocation')
    assert started, 'runtime-restarted: the ConfigMap maintenance-baseline in ' + NS + ' is missing; do not delete it'
    state = systemd_property('ActiveState')
    assert state == 'active', "runtime-restarted: the containerd service is '" + (state or 'unknown') + "', expected active"
    assert systemd_property('InvocationID') != started, 'runtime-restarted: containerd still runs the process that started with the lab; restart the service'

if wants('probe-pods-replaced'):
    old = baseline('probe-uids').split()
    assert old, 'probe-pods-replaced: the ConfigMap maintenance-baseline in ' + NS + ' is missing; do not delete it'
    listing = command(['kubectl', '-n', NS, 'get', 'pods', '-l', 'app=probe', '-o', 'json'], success=False)
    pods = json.loads(listing.stdout).get('items', []) if listing.returncode == 0 else []
    kept = [pod['metadata']['name'] for pod in pods if pod['metadata']['uid'] in old]
    assert not kept, 'probe-pods-replaced: drain the node so that the probe Pods are evicted and recreated; still running: ' + ', '.join(kept)
    available = command(['kubectl', '-n', NS, 'get', 'deployment', 'probe', '-o', 'jsonpath={.status.availableReplicas}'], success=False).stdout.strip()
    assert int(available or 0) >= 2, 'probe-pods-replaced: Deployment probe has ' + (available or '0') + ' available replicas, expected 2'

if wants('node-in-service'):
    result = command(['kubectl', 'get', 'node', NODE_NAME, '-o', 'json'], success=False)
    assert result.returncode == 0, 'node-in-service: node ' + NODE_NAME + ' is not readable'
    node = json.loads(result.stdout)
    ready = [c['status'] for c in node['status'].get('conditions', []) if c['type'] == 'Ready']
    assert ready == ['True'], 'node-in-service: node ' + NODE_NAME + ' is not Ready'
    assert not node['spec'].get('unschedulable'), 'node-in-service: node ' + NODE_NAME + ' is still cordoned (SchedulingDisabled)'
